package com.myassist.customer.ui;
import android.content.Intent; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import androidx.recyclerview.widget.*; import com.myassist.customer.R; import com.myassist.customer.model.Models; import com.myassist.customer.network.*; import org.json.*; import java.util.*;
public class TrackOrdersActivity extends AppCompatActivity { LinearLayout list; TextView error; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_track_orders);list=findViewById(R.id.list);error=findViewById(R.id.tvError);load();} void load(){ApiService.run(ApiService.get("api/v1/customer/requests"),x->x,new ApiService.Callback<JSONObject>(){public void onSuccess(JSONObject o){runOnUiThread(()->{list.removeAllViews();JSONArray a=o.optJSONArray("items");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);TextView v=new TextView(TrackOrdersActivity.this);v.setText("#"+x.optInt("id")+"  "+x.optString("service_type")+"\n"+x.optString("status"));v.setPadding(24,24,24,24);int id=x.optInt("id");v.setOnClickListener(z->startActivity(new Intent(this,RequestDetailsActivity.class).putExtra("request_id",id)));list.addView(v);}});}public void onError(ApiClient.ApiException e){runOnUiThread(()->error.setText(e.userMessage));}});} }